steps.sampleSolution:
type Conta struct {
    Titular string
    saldo   int
}

func Depositar(c *Conta, valor int) {
    c.saldo += valor
}

func main() {
    conta := Conta{Titular: "Ana"}
    Depositar(&conta, 100)
}
